const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('zh-TW',{maximumFractionDigits:d,minimumFractionDigits:d}):'—',day=s=>/^\d{8}$/.test(s??'')?s.slice(0,4)+'/'+s.slice(4,6)+'/'+s.slice(6):'—';
export function statisticsHTML(data,extremesScope='recent'){
 if(!data||data.version!==1||!Array.isArray(data.windows)||!Array.isArray(data.daily)||!Array.isArray(data.history))throw Error('統計資料格式無效');
 return `<section class="panel statisticsPanel"><div class="sectionhead"><h2>台指期日盤平均震幅</h2><span>單位：點</span></div><p>資料期間：${day(data.from)}～${day(data.latest)}，共 ${data.count} 個交易日。每日震幅＝當日所列契約的最高價－最低價。</p><div class="statsgrid explainedStats">${data.windows.map(w=>`<div><span>近 ${w.days} 個交易日平均震幅</span><strong>${w.average==null?'資料不足':fmt(w.average)+' 點'}</strong><p>${w.average==null?`目前 ${w.count} 日／需要 ${w.days} 日，尚缺 ${w.missing} 日。`:`${day(w.from)}～${day(w.to)}；震幅合計 ÷ ${w.days}。`}</p></div>`).join('')}</div><div class="notice">現有 ${data.count} 日平均：<strong>${fmt(data.availableAverage)} 點</strong>。此為現有資料平均，不代表完整 20、60 或 120 日平均。</div></section>${extremesHTML(extremesScope==='all'?data.cumulativeExtremes:data.extremes,{scope:extremesScope,recent:data.extremes,cumulative:data.cumulativeExtremes})}${previousRangeHTML(data.previousRange)}`;
}
const hm=sec=>`${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec%3600/60)).padStart(2,'0')}`;
const bucketLabel=b=>b.start===49500?'13:45（收盤）':hm(b.start)+'～'+hm(b.end);
function extremeChart(e,key,title,color){const max=Math.max(1,...e.buckets.map(b=>b[key])),bar=13,row=23,top=22,height=e.buckets.length*row+32;return `<svg viewBox="0 0 510 ${height}" role="img" aria-label="${title}">${e.buckets.map((b,i)=>{const y=top+i*row,n=b[key],p=e.count?n/e.count*100:0;return `<text x="0" y="${y+10}" fill="#a5b4bd" font-size="11">${bucketLabel(b)}</text><rect x="113" y="${y}" width="${n/max*278}" height="${bar}" rx="2" fill="${color}"><title>${bucketLabel(b)}：${n}日，${fmt(p,0)}%</title></rect><text x="${120+n/max*278}" y="${y+10}" fill="#dce5e9" font-size="11">${n}日（${fmt(p,0)}%）</text>`}).join('')}</svg>`}
export function extremesHTML(e,options={}){if(!e||!Array.isArray(e.buckets)||!Array.isArray(e.daily))return '<section class="panel statisticsPanel"><h2>近20交易日日高／日低時段</h2><p>時段資料尚未完成更新。</p></section>';
 const all=options.scope==='all',title=all?'累積日高／日低出現時段':'近20交易日日高／日低出現時段';
 const most=key=>{const n=Math.max(0,...e.buckets.map(b=>b[key]));return n?e.buckets.filter(b=>b[key]===n).map(bucketLabel).join('、')+`：各${n}日（${fmt(n/e.count*100,0)}%）`:'尚無資料'};
 return `<section class="panel statisticsPanel extremesPanel"><div class="extremesHeading"><h2>${title}</h2><label class="extremesScopeLabel">統計範圍<select id="extremesScope" aria-label="日高日低統計範圍"><option value="recent" ${all?'':'selected'}>近20交易日</option><option value="all" ${all?'selected':''} ${options.cumulative?'':'disabled'}>全部累積</option></select></label><button class="distributionToggle" aria-expanded="false" onclick="const box=this.closest('section').querySelector('.chartDisclosure');box.open=!box.open;this.setAttribute('aria-expanded',String(box.open))">查看日高／日低分布圖</button></div><p>${day(e.from)}～${day(e.to)}，${all?`累積 ${e.count} 個已完成交易日。新增交易日持續累加，不移除較早日期。`:`已完成 ${e.count}／20 個交易日。${e.complete?'':'資料不足20日，以下依現有可判定日數計算，未補入更早日期。'}`}</p><p class="hint">以收盤後確定的全日最高價、最低價為準，各取第一次出現的時段；盤中暫時高低點不計入。每個交易日各貢獻一次日高、一次日低，依15分鐘分組。</p><div class="extremeHighlights"><p><strong>日高最常出現</strong><br>${most('high')}</p><p><strong>日低最常出現</strong><br>${most('low')}</p></div><details class="chartDisclosure"><summary class="distributionInnerSummary">收合分布圖</summary><div class="historyCharts"><section><h3>日高時段分布</h3>${extremeChart(e,'high',(all?'全部累積':'近20交易日')+'日高時段分布','#e1867d')}</section><section><h3>日低時段分布</h3>${extremeChart(e,'low',(all?'全部累積':'近20交易日')+'日低時段分布','#62c1aa')}</section></div>${extremesComparison(options.recent,options.cumulative)}</details><p class="hint">每張圖的天數合計 ${e.count} 日，比例以 ${e.count} 日為分母；若比例四捨五入，顯示合計可能略有差異。以網站已保存的期交所日盤逐筆重算，每日選最近月份單一契約，不混合多個月份。</p></section>`;
}

function extremesComparison(recent,all){
 if(!recent||!all)return '';
 const value=(n,total)=>`${n}日（${fmt(total?n/total*100:0,1)}%）`;
 return `<h3>近20日與全部累積對照</h3><p>近20日：${day(recent.from)}～${day(recent.to)}，${recent.count}日；全部累積：${day(all.from)}～${day(all.to)}，${all.count}日。</p><div class="statisticsTable"><table><thead><tr><th>時段</th><th>近20日日高</th><th>累積日高</th><th>近20日日低</th><th>累積日低</th></tr></thead><tbody>${recent.buckets.map((b,i)=>`<tr><td>${bucketLabel(b)}</td><td>${value(b.high,recent.count)}</td><td>${value(all.buckets[i].high,all.count)}</td><td>${value(b.low,recent.count)}</td><td>${value(all.buckets[i].low,all.count)}</td></tr>`).join('')}</tbody></table></div>`;
}

function cumulativeChart(direction,title,color){
 const bars=direction.points.map((p,i)=>{const y=30+i*36;return `<text x="0" y="${y+12}" fill="#a5b4bd" font-size="12">至少${p.points}點</text><rect x="96" y="${y}" width="${(p.percent??0)*2.65}" height="20" rx="3" fill="${color}"><title>${p.count}／${direction.count}日，${fmt(p.percent,1)}%</title></rect><text x="${104+(p.percent??0)*2.65}" y="${y+14}" fill="#e7eef1" font-size="12">${p.percent==null?'無樣本':fmt(p.percent,1)+'%'}（${p.count}日）</text>`}).join('');
 return `<section><h3>${title}</h3><p>分母：${direction.count}個${title.startsWith('突破')?'突破':'跌破'}日</p><svg viewBox="0 0 510 330" role="img" aria-label="${title}累積比例圖">${bars}</svg></section>`;
}
export function previousRangeHTML(p){
 if(!p)return '';
 const levels=[100,200,300,500],pairs=levels.map(n=>({n,up:p.up.points.find(x=>x.points===n),down:p.down.points.find(x=>x.points===n)}));
 const large=pairs.filter(x=>x.n>=200),comparable=p.up.count>0&&p.down.count>0;
 const finding=!comparable?'目前樣本不足，暫不比較兩個方向。':large.every(x=>x.down.percent>x.up.percent)?'目前樣本中，跌破昨低後至少延伸200、300、500點的比例，均高於突破昨高後的上行比例。這不表示多數跌破都會大跌，也不代表未來必然如此。':large.every(x=>x.up.percent>x.down.percent)?'目前樣本中，突破昨高後至少延伸200、300、500點的比例，均高於跌破昨低後的下行比例。這不代表未來必然如此。':'目前兩方向的延伸比例依目標點數而異，沒有一致較高的方向。';
 return `<section class="panel previousRangePanel"><details class="statDisclosure"><summary>昨高昨低法 · 突破與跌破累積比例圖</summary><div class="disclosureBody"><h3>統計條件與讀法</h3><p>僅統計昨低＜今日開盤＜昨高的交易日。突破後上行點數＝當日最高價－昨高；跌破後下行點數＝昨低－當日最低價。比例代表已突破／跌破的交易日中，至少延伸至該點數的比例，各方向分母不同。</p><p>每個交易日各方向最多計一次；同一天可能同時突破昨高與跌破昨低。未突破或未跌破的日期不納入該方向分母。</p><div class="historyCharts">${cumulativeChart(p.up,'突破昨高後繼續上行','#e1867d')}${cumulativeChart(p.down,'跌破昨低後繼續下行','#62c1aa')}</div><h3>目前資料呈現的現象</h3><p>${finding}</p><div class="statisticsTable"><table><thead><tr><th>至少延伸</th><th>突破昨高後繼續上行</th><th>跌破昨低後繼續下行</th></tr></thead><tbody>${pairs.map(x=>`<tr><td>${x.n}點</td><td>${fmt(x.up.percent,1)}%</td><td>${fmt(x.down.percent,1)}%</td></tr>`).join('')}</tbody></table></div><h3>使用時最重要的提醒</h3><p class="notice"><strong>到過目標價，不代表交易能順利停利。</strong>日線無法判斷突破／跌破後，是否先反向觸發停損，再到達目標；這些比例不是交易勝率。</p><h3>資料與更新標示</h3><p>滾動近三年：${day(p.from)}～${day(p.to)}；資料截至${day(p.to)}。可分析${p.considered}日，其中${p.inside}日開盤介於昨高昨低之間。突破${p.up.count}日，跌破${p.down.count}日。${p.skipped?`另有${p.skipped}日缺少必要欄位而未納入。`:''}</p><p>每日更新流程加入完成交易日後重新計算，圖表及比較說明同步更新。來源為使用者確認的Dropbox台指期日盤歷史資料及其後的逐日Excel；歷史來源未列月份，未調整換月價差，未計滑價與成本。</p></div></details></section>`;
}
